/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const input_fields = api.context.props.payload.guided_context.input_fields;
	const selectedTableFields = input_fields && input_fields.length && input_fields.split(',').map(field => {
		return {
			id: field,
			label: field
		};
	});
	return {
		propName: 'selectedTableFields',
		value: selectedTableFields
	};
}
